20	/** Reads data from underlying ReadBuffer bit by bit, max 64 bits at once.
21	 *
22	 * reads MSB bits first, imagine that you have a data:
23	 * 11110000 10101010 00100100 11111110
24	 *
25	 * Given that r is BitReader created with a ReadBuffer that reads from data above:
26	 *  r.readBits(3)  => 0b111
27	 *  r.readBit()    => 0b1
28	 *  r.readBits(8)  => 0b1010 // 4 leading zero-bits are not shown
29	 *  r.readBit()    => 0b1
30	 *  r.readBit()    => 0b0
31	 *  r.readBits(15) => 0b10001001001111111
32	 *  r.readBit()    => 0b0
33	**/
34	
35	class BitReader
36	{
37	    using BufferType = unsigned __int128;
38	
39	    const char * source_begin;
40	    const char * source_current;
41	    const char * source_end;
42	
43	    BufferType bits_buffer;
44	    UInt8 bits_count;
45	
46	public:
47	    BitReader(const char * begin, size_t size)
48	        : source_begin(begin),
49	          source_current(begin),
50	          source_end(begin + size),
51	          bits_buffer(0),
52	          bits_count(0)
53	    {}
54	
55	    ~BitReader() = default;
56	
57	    // reads bits_to_read high-bits from bits_buffer
58	    ALWAYS_INLINE inline UInt64 readBits(UInt8 bits_to_read)
59	    {
60	        if (bits_to_read > bits_count)
61	            fillBitBuffer();
62	
63	        return getBitsFromBitBuffer<CONSUME>(bits_to_read);
64	    }
65	
66	    inline UInt8 peekByte()
67	    {
68	        if (bits_count < 8)
69	            fillBitBuffer();
70	
71	        return getBitsFromBitBuffer<PEEK>(8);
72	    }
73	
74	    ALWAYS_INLINE inline UInt8 readBit()
75	    {
76	        return static_cast<UInt8>(readBits(1));
77	    }
78	
79	    // skip bits from bits_buffer
80	    inline void skipBufferedBits(UInt8 bits)
81	    {
82	        bits_buffer <<= bits;
83	        bits_count -= bits;
84	    }
85	
86	
87	    inline bool eof() const
88	    {
89	        return bits_count == 0 && source_current >= source_end;
90	    }
91	
92	    // number of bits that was already read by clients with readBits()
93	    inline UInt64 count() const
94	    {
95	        return (source_current - source_begin) * 8 - bits_count;
96	    }
