104	    enum GetBitsMode {CONSUME, PEEK};
105	    // read data from internal buffer, if it has not enough bits, result is undefined.
106	    template <GetBitsMode mode>
107	    inline UInt64 getBitsFromBitBuffer(UInt8 bits_to_read)
108	    {
109	        assert(bits_to_read > 0);
110	
111	        // push down the high-bits
112	        const UInt64 result = static_cast<UInt64>(bits_buffer >> (sizeof(bits_buffer) * 8 - bits_to_read));
113	
114	        if constexpr (mode == CONSUME)
