152	class BitWriter
153	{
154	    using BufferType = unsigned __int128;
155	
156	    char * dest_begin;
157	    char * dest_current;
158	    char * dest_end;
159	
160	    BufferType bits_buffer;
161	    UInt8 bits_count;
162	
163	    static constexpr UInt8 BIT_BUFFER_SIZE = sizeof(bits_buffer) * 8;
164	
165	public:
166	    BitWriter(char * begin, size_t size)
167	        : dest_begin(begin),
168	          dest_current(begin),
169	          dest_end(begin + size),
170	          bits_buffer(0),
171	          bits_count(0)
172	    {}
173	
174	    ~BitWriter()
175	    {
176	        flush();
177	    }
178	
179	    // write `bits_to_write` low-bits of `value` to the buffer
180	    inline void writeBits(UInt8 bits_to_write, UInt64 value)
181	    {
182	        assert(bits_to_write > 0);
183	
184	        UInt32 capacity = BIT_BUFFER_SIZE - bits_count;
185	        if (capacity < bits_to_write)
186	        {
187	            doFlush();
188	            capacity = BIT_BUFFER_SIZE - bits_count;
189	        }
190	
191	        // write low bits of value as high bits of bits_buffer
192	        const UInt64 mask = maskLowBits<UInt64>(bits_to_write);
193	        BufferType v = value & mask;
194	        v <<= capacity - bits_to_write;
195	
196	        bits_buffer |= v;
197	        bits_count += bits_to_write;
198	    }
199	
200	    // flush contents of bits_buffer to the dest_current, partial bytes are completed with zeroes.
201	    inline void flush()
202	    {
203	        bits_count = (bits_count + 8 - 1) & ~(8 - 1); // align up to 8-bytes, so doFlush will write all data from bits_buffer
204	        while (bits_count != 0)
205	            doFlush();
206	    }
207	
208	    inline UInt64 count() const
209	    {
210	        return (dest_current - dest_begin) * 8 + bits_count;
211	    }
212	
213	private:
214	    void doFlush()
215	    {
216	        // write whole bytes to the dest_current, leaving partial bits in bits_buffer
217	        const size_t available = dest_end - dest_current;
218	        const size_t to_write = std::min<size_t>(sizeof(UInt64), bits_count / 8); // align to 8-bit boundary
219	
220	        if (available < to_write)
221	        {
222	            throw Exception(ErrorCodes::CANNOT_WRITE_AFTER_END_OF_BUFFER,
223	                "Can not write past end of buffer. Space available {} bytes, required to write {} bytes.",
224	                available, to_write);
225	        }
226	
227	        const auto tmp_buffer = __builtin_bswap64(static_cast<UInt64>(bits_buffer >> (sizeof(bits_buffer) - sizeof(UInt64)) * 8));
228	        memcpy(dest_current, &tmp_buffer, to_write);
229	        dest_current += to_write;
230	
231	        bits_buffer <<= to_write * 8;
232	        bits_count -= to_write * 8;
233	    }
